body.script:
(function () {
    var entree = document.getElementById("brg-cible");
    var envoi = document.getElementById("brg-envoi");
    var etat = document.getElementById("brg-etat");
    var resultat = document.getElementById("brg-resultat");
    function observer() {
        var c = entree.value.trim();
        if (!c) return;
        resultat.hidden = true;
        etat.textContent = "Braignak observe…";
        envoi.disabled = true; entree.disabled = true;
        fetch("/community/braignak/observer", {
            method: "POST",
            headers: {"Content-Type": "application/json"},
            body: JSON.stringify({
                jsonrpc: "2.0",
                params: {cible: c}
            })
        }).then(function (r) { return r.json(); }).then(function (d) {
            etat.textContent = "";
            var res = d && d.result;
            if (!res) { resultat.textContent = "Réponse vide du serveur."; }
            else if (res.erreur) { resultat.textContent = res.erreur; }
            else { resultat.textContent = res.reponse; }
            resultat.hidden = false;
        }).catch(function () {
            etat.textContent = "";
            resultat.textContent = "Impossible de joindre le serveur.";
            resultat.hidden = false;
        }).finally(function () {
            envoi.disabled = false; entree.disabled = false;
            entree.focus();
        });
    }
    envoi.addEventListener("click", observer);
    entree.addEventListener("keydown", function (e) {
        if (e.key === "Enter") observer();
    });
    entree.focus();
})();
